package com.jadhavr.erp.email.service;import com.jadhavr.erp.auth.service.DistributedRateLimiter;import com.jadhavr.erp.email.config.MailProperties;import com.jadhavr.erp.email.entity.*;import com.jadhavr.erp.email.repository.*;import com.jadhavr.erp.user.entity.User;import com.jadhavr.erp.user.repository.UserRepository;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;
@Service public class AccountTokenService{private final UserRepository users;private final PasswordResetTokenRepository resets;private final EmailVerificationTokenRepository verifications;private final EmailNotificationService emails;private final PasswordEncoder encoder;private final MailProperties props;private final DistributedRateLimiter rate;private final SecureRandom random=new SecureRandom();public AccountTokenService(UserRepository u,PasswordResetTokenRepository r,EmailVerificationTokenRepository v,EmailNotificationService e,PasswordEncoder p,MailProperties m,DistributedRateLimiter rate){users=u;resets=r;verifications=v;emails=e;encoder=p;props=m;this.rate=rate;}
@Transactional public void forgot(String email){String normalized=email.trim().toLowerCase();if(limited("reset:"+normalized))return;users.findByEmail(normalized).ifPresent(u->{LocalDateTime now=LocalDateTime.now();resets.findByUserIdAndUsedAtIsNullAndRevokedAtIsNull(u.getId()).forEach(t->t.setRevokedAt(now));String raw=token();PasswordResetToken t=new PasswordResetToken();t.setUser(u);t.setTokenHash(hash(raw));t.setExpiresAt(now.plusMinutes(props.getTokenExpiryMinutes()));resets.save(t);emails.queuePasswordResetEmail(u,raw,t.getExpiresAt());});}
@Transactional public void reset(String raw,String password){PasswordResetToken t=resets.findByTokenHash(hash(raw)).orElseThrow(()->new IllegalArgumentException("Invalid or expired password reset token"));validate(t.getUsedAt(),t.getRevokedAt(),t.getExpiresAt());User u=t.getUser();u.setPasswordHash(encoder.encode(password));u.setMustChangePassword(false);users.save(u);t.setUsedAt(LocalDateTime.now());resets.save(t);emails.queuePasswordChangedEmail(u);}
@Transactional public void requestVerification(User u){if(limited("verify:"+u.getEmail()))return;LocalDateTime now=LocalDateTime.now();verifications.findByUserIdAndUsedAtIsNullAndRevokedAtIsNull(u.getId()).forEach(t->t.setRevokedAt(now));String raw=token();EmailVerificationToken t=new EmailVerificationToken();t.setUser(u);t.setTokenHash(hash(raw));t.setExpiresAt(now.plusMinutes(props.getTokenExpiryMinutes()));verifications.save(t);emails.queueEmailVerificationEmail(u,raw,t.getExpiresAt());}
@Transactional public void verify(String raw){EmailVerificationToken t=verifications.findByTokenHash(hash(raw)).orElseThrow(()->new IllegalArgumentException("Invalid or expired verification token"));validate(t.getUsedAt(),t.getRevokedAt(),t.getExpiresAt());User u=t.getUser();u.setEmailVerified(true);users.save(u);t.setUsedAt(LocalDateTime.now());verifications.save(t);emails.queueEmailVerifiedEmail(u);}
private boolean limited(String key){return !rate.tryAcquire("account-token",key,1,Duration.ofMinutes(1));}private void validate(LocalDateTime used,LocalDateTime revoked,LocalDateTime expiry){if(used!=null||revoked!=null||expiry.isBefore(LocalDateTime.now()))throw new IllegalArgumentException("Invalid or expired token");}private String token(){byte[]b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
